<?php
require_once 'auth.php';require_role(['super_admin']);require_once 'db.php';
$message='';$type='error';
if($_SERVER['REQUEST_METHOD']==='POST'){
 try {

 if(!verify_csrf())$message='Invalid request.';else{
  $action=$_POST['action']??'create';$username=trim($_POST['username']??'');
  if($action==='toggle'){$active=(int)($_POST['active']??0);if($username===$_SESSION['admin_username'])$message='You cannot disable your own account.';else{$u=mysqli_prepare($conn,'UPDATE admin SET is_active=? WHERE username=?');mysqli_stmt_bind_param($u,'is',$active,$username);mysqli_stmt_execute($u);audit_log($conn,'STATUS','admin',$username,$active?'Activated':'Deactivated');$message='Admin status updated.';$type='success';}}
  elseif($action==='role'){$role=$_POST['role']??'';if(!in_array($role,['super_admin','registrar','data_entry'],true))$message='Invalid role.';else{$u=mysqli_prepare($conn,'UPDATE admin SET role=? WHERE username=?');mysqli_stmt_bind_param($u,'ss',$role,$username);mysqli_stmt_execute($u);audit_log($conn,'ROLE','admin',$username,'Role changed to '.$role);$message='Role updated.';$type='success';}}
  else{$password=$_POST['password']??'';$role=$_POST['role']??'data_entry';if($username===''||!valid_admin_password($password)||!in_array($role,['super_admin','registrar','data_entry'],true))$message='Enter valid username, role and password (12-72 characters, uppercase, lowercase and number).';else{$c=mysqli_prepare($conn,'SELECT username FROM admin WHERE username=?');mysqli_stmt_bind_param($c,'s',$username);mysqli_stmt_execute($c);if(mysqli_fetch_assoc(mysqli_stmt_get_result($c)))$message='Username already exists.';else{$hash=password_hash($password,PASSWORD_DEFAULT);$i=mysqli_prepare($conn,'INSERT INTO admin(username,password,role,is_active) VALUES(?,?,?,1)');mysqli_stmt_bind_param($i,'sss',$username,$hash,$role);mysqli_stmt_execute($i);audit_log($conn,'ADMIN_CREATED','admin',$username,'Created as '.$role);$message='Administrator created.';$type='success';}}}
 }

 } catch(mysqli_sql_exception $ex) { mysqli_rollback($conn); $message='This change could not be saved. The record may be locked, protected or changed by another user. Refresh and try again.'; $type='error'; }
}
$r=mysqli_query($conn,'SELECT username,role,is_active,locked_until FROM admin ORDER BY username');$admins=[];while($x=mysqli_fetch_assoc($r))$admins[]=$x;
?><!DOCTYPE html><html><head><meta charset="UTF-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Admin Users</title><link rel="icon" href="favicon.svg" type="image/svg+xml"><link rel="stylesheet" href="modern-ui.css?v=20261006-modern2"></head><body><div class="main-wrapper"><?php include 'admin_nav.php';?><main class="content"><section class="page-heading"><div><span class="page-kicker">Access Control</span><h1>Admin Users</h1><p>Create administrators and assign least-privilege roles.</p></div></section><?php if($message):?><div class="message <?=$type?>"><?=e($message)?></div><?php endif;?><div class="feature-grid"><section class="feature-card"><h2>Create Administrator</h2><form method="post"><input type="hidden" name="csrf_token" value="<?=e(csrf_token())?>"><input type="hidden" name="action" value="create"><label>Username</label><input name="username" required><label>Password</label><input type="password" name="password" minlength="12" maxlength="72" required><label>Role</label><select name="role"><option value="data_entry">Data Entry</option><option value="registrar">Registrar</option><option value="super_admin">Super Admin</option></select><div class="button-row"><input type="submit" value="Create Admin"></div></form></section><section class="feature-card wide-card"><h2>Administrators</h2><div class="table-wrapper"><table class="results-table"><tr><th>Username</th><th>Role</th><th>Status</th><th>Locked Until</th><th>Actions</th></tr><?php foreach($admins as $a):?><tr><td><strong><?=e($a['username'])?></strong></td><td><form method="post" class="inline-form"><input type="hidden" name="csrf_token" value="<?=e(csrf_token())?>"><input type="hidden" name="action" value="role"><input type="hidden" name="username" value="<?=e($a['username'])?>"><select name="role"><?php foreach(['data_entry','registrar','super_admin'] as $ro):?><option value="<?=$ro?>" <?=$a['role']===$ro?'selected':''?>><?=e(role_label($ro))?></option><?php endforeach;?></select><button class="small-btn">Save</button></form></td><td><?=$a['is_active']?'Active':'Inactive'?></td><td><?=e($a['locked_until']??'')?></td><td><?php if($a['username']!==($_SESSION['admin_username']??'')):?><form method="post" class="inline-form"><input type="hidden" name="csrf_token" value="<?=e(csrf_token())?>"><input type="hidden" name="action" value="toggle"><input type="hidden" name="username" value="<?=e($a['username'])?>"><input type="hidden" name="active" value="<?=$a['is_active']?0:1?>"><button class="small-btn <?=$a['is_active']?'btn-danger':''?>"><?=$a['is_active']?'Disable':'Enable'?></button></form><?php endif;?></td></tr><?php endforeach;?></table></div></section></div></main><?php include 'footer.php';?></div></body></html>
